SELECT dbs.code as systemCode, dcid.id as detailId, dcid.next_level_id as nextLevelId, dcid.main_id as cfgInputId, dci.bill_type as billType FROM "dmp_cfg_input_detail" AS dcid INNER JOIN dmp_cfg_input AS dci ON dci.ID = dcid.main_id INNER JOIN dmp_basic_system AS dbs ON dbs.ID = dci.system_id WHERE dcid.is_deleted = FALSE AND dci.is_deleted = FALSE AND dbs.is_deleted = FALSE AND dci.bill_type IN
#{t}
AND dcid.next_level_id IN
#{nextLevelId}
AND dbs.code ILIKE ANY ( ARRAY
#{systemCode}
) GROUP BY dbs.code, dcid.id, dcid.next_level_id, dcid.main_id, dci.bill_type
